import * as React from 'react'
import * as SliderPrimitive from '@radix-ui/react-slider'
import { cn } from './cn'

export interface SliderProps extends React.ComponentProps<typeof SliderPrimitive.Root> {
  /** The thumb's accessible name: the thumb, not the root, is the focusable `slider`. */
  thumbLabel?: string
  /** Ids of the elements describing the thumb. */
  thumbDescribedBy?: string
}

const Slider = React.forwardRef<
  React.ElementRef<typeof SliderPrimitive.Root>,
  SliderProps
>(({ className, thumbLabel, thumbDescribedBy, ...props }, ref) => {
  return (
    <SliderPrimitive.Root
      ref={ref}
      className={cn(
        'uhuu:relative uhuu:flex uhuu:w-full uhuu:touch-none uhuu:select-none uhuu:items-center uhuu:data-[disabled]:opacity-50',
        className
      )}
      {...props}
    >
      <SliderPrimitive.Track className="uhuu:relative uhuu:h-1.5 uhuu:w-full uhuu:grow uhuu:overflow-hidden uhuu:rounded-full uhuu:bg-gray-200">
        <SliderPrimitive.Range className="uhuu:absolute uhuu:h-full uhuu:bg-gray-900" />
      </SliderPrimitive.Track>
      <SliderPrimitive.Thumb aria-label={thumbLabel} aria-describedby={thumbDescribedBy} className="uhuu:block uhuu:h-4 uhuu:w-4 uhuu:rounded-full uhuu:border-2 uhuu:border-gray-900 uhuu:bg-(--uhuu-shell-surface) uhuu:shadow uhuu:transition-colors uhuu:focus-visible:outline-none uhuu:focus-visible:ring-2 uhuu:focus-visible:ring-gray-400 uhuu:focus-visible:ring-offset-2 uhuu:disabled:pointer-events-none uhuu:disabled:opacity-50" />
    </SliderPrimitive.Root>
  )
})
Slider.displayName = SliderPrimitive.Root.displayName

export { Slider }
