import { warnImageFailed } from '../utility/warn-once.js'

interface UseImageLoadFailureOptions {
  onError?: React.ReactEventHandler<HTMLImageElement>
}

/** An image that fails prints empty: say which (once per URL), then hand the event to `onError`. */
export const useImageLoadFailure = ({
  onError,
}: UseImageLoadFailureOptions) => {
  const handleError: React.ReactEventHandler<HTMLImageElement> = (event) => {
    warnImageFailed(event.currentTarget.currentSrc || event.currentTarget.src)
    onError?.(event)
  }

  return handleError
}
