// src/uhuu/editor-shell/document/document-options-core.js
// Pure, DOM-free core of EditorShell.DocumentOptions: how a choice reaches the uhuu document
// editor. Values are read, matched and typed by option-core.js, as for page options; the React
// control is document-options.tsx; docs/document-options.md describes the contract.
//
// A document option is a top-level payload key the template reads (`payload.language`), the same
// key and values the platform's template theme options wrote, so documents need no migration.

import {
  coerceOptionValue,
  findOptionChoice,
  isOptionOn,
  optionField,
  optionType,
  optionValueType,
  readOptionValue,
  sameOptionValue,
} from './option-core.js';

/** The payload key the option writes: `field`, else `id`, else the 0.4 `key`. */
export const documentOptionKey = optionField;

// The 0.4 names, kept for templates that import them.
export const documentOptionType = optionType;
export const documentOptionValueType = optionValueType;
export const sameDocumentOptionValue = sameOptionValue;
export const findDocumentOptionChoice = findOptionChoice;
export const isDocumentOptionOn = isOptionOn;
export const coerceDocumentOptionValue = coerceOptionValue;

/** The value the document holds for the option: `payload[key]`, else the definition's default. */
export function readDocumentOption(payload, definition) {
  return readOptionValue(payload, definition);
}

/**
 * How a choice is written:
 * - `patch`: `$uhuu.editor.post({ action: 'patchPayload', patch })`, a person's edit that the
 *   editor renders back. The transport alone does not establish that the editor handles the
 *   message, so the control waits for the payload to come back (`DOCUMENT_OPTION_PATCH_TIMEOUT`)
 *   and uses the field dialog when it does not.
 * - `dialog`: the released editor's field dialog (`$uhuu.editDialog`), opened with the choice.
 * - `none`: no editor on the page; the control keeps the choice and calls `onChange`.
 */
export function documentOptionWriteMode(uhuu) {
  if (typeof uhuu?.editor?.post === 'function') return 'patch';
  if (typeof uhuu?.editDialog === 'function') return 'dialog';
  return 'none';
}

/** How long a patch waits for the editor to render it back before the field dialog opens. */
export const DOCUMENT_OPTION_PATCH_TIMEOUT = 1500;

/** The `patchPayload` message that writes a choice, typed as the option declares. */
export function documentOptionPatchMessage(definition, value) {
  return { action: 'patchPayload', patch: { [documentOptionKey(definition)]: coerceOptionValue(definition, value) } };
}

/**
 * The `$uhuu.editDialog()` request for an option, supported by released editors: the editor's
 * select or switch field for the top-level key (a slider or counter is a text field). That field
 * renders plain strings, so labels are resolved (`localize`) and values stringified; it saves
 * strings, as the platform's dropdown did. `value` is the choice the dialog opens with.
 */
export function documentOptionEditDialog(definition, value, localize = (text) => (typeof text === 'string' ? text : undefined)) {
  const path = documentOptionKey(definition);
  const label = localize(definition.label) ?? path;
  const type = optionType(definition);
  if (type === 'toggle') {
    return { path, type: 'switch', label, value: isOptionOn(value) };
  }
  const shown = value === undefined || value === null ? {} : { value: String(value) };
  if (type === 'slider' || type === 'counter') {
    return { path, label, ...shown };
  }
  const choices = Array.isArray(definition.options) ? definition.options : [];
  return {
    path,
    type: 'select',
    label,
    ...shown,
    options: choices.map((choice) => ({
      value: String(choice.value),
      label: localize(choice.label) ?? String(choice.value),
    })),
  };
}
