/**
 * Chart colors for chart libraries, which want plain hex. A kit's chart colors reach templates only
 * when the brand set them: Brand Kit publishes `--chart-1…5` in `runtime` only then, so on Auto
 * every template keeps its own palette. `brandChartPalette` returns the brand's colors when it set
 * them, else the template's `fallback`, as `#rrggbb`.
 *
 * Pure and DOM-free.
 */
import { extendChartPalette, normalizeColor, toHex } from '@uhuu/brandkit';
import { isPlainObject, textOf } from '../utility/json.js';
import { brandKitRuntime, toPrintSafeColor } from './brand-kit-css-vars.js';

/**
 * `#rrggbb` for a colour the kit may hold (hex, `rgb()`, HSL, `oklch()`, `oklab()`); alpha is
 * dropped. `undefined` for anything else, keywords included. Conversion is the package's.
 */
export function colorToHex(value) {
  const color = toPrintSafeColor(value);
  if (!color || /^[a-z]+$/i.test(color)) return undefined;
  const normalized = normalizeColor(color);
  return normalized ? toHex(normalized) : undefined;
}

/** The chart colors the brand set, in series order, as written in the kit. Empty on Auto. */
export function brandKitChartColors(brandKit) {
  if (!isPlainObject(brandKit)) return [];
  const runtime = brandKitRuntime(brandKit);
  if (runtime) {
    // Published kits: present only when authored.
    return [1, 2, 3, 4, 5].map((n) => textOf(runtime.light[`--chart-${n}`])).filter(Boolean);
  }
  // Template-bundled kits without a runtime: semantic chart1…5.
  const semantic = isPlainObject(brandKit.tokens?.light?.semantic) ? brandKit.tokens.light.semantic : {};
  return [1, 2, 3, 4, 5].map((n) => textOf(semantic[`chart${n}`])).filter(Boolean);
}

/**
 * The palette a chart should use, as `#rrggbb`: the brand's chart colors when it set them, else
 * `fallback` (the template's own). `count` asks for that many series: past the brand's five,
 * `extendChartPalette` from @uhuu/brandkit continues the palette (the same series N as Brand Kit
 * and Studio show); a template fallback repeats.
 *
 * @param {object|null|undefined} brandKit
 * @param {{ fallback?: string[], count?: number }} [options]
 * @returns {{ colors: string[], source: 'brand'|'template' }}
 */
export function brandChartPalette(brandKit, options = {}) {
  const authored = brandKitChartColors(brandKit).map(normalizeColor).filter(Boolean);
  const fallback = (Array.isArray(options.fallback) ? options.fallback : []).map(colorToHex).filter(Boolean);
  const wanted = Number.isInteger(options.count) && options.count > 0 ? options.count : undefined;
  if (authored.length) {
    const colors = extendChartPalette(authored, wanted ?? authored.length).map((color) => toHex(color)).filter(Boolean);
    return { colors, source: 'brand' };
  }
  const count = wanted ?? fallback.length;
  const colors = fallback.length ? Array.from({ length: count }, (_, index) => fallback[index % fallback.length]) : [];
  return { colors, source: 'template' };
}

/** A role's colour from the kit: published `runtime` first, then the semantic token. */
function roleColor(brandKit, runtimeName, semanticKey) {
  const runtime = brandKitRuntime(brandKit);
  const fromRuntime = runtime ? textOf(runtime.light[`--${runtimeName}`]) : undefined;
  const semantic = isPlainObject(brandKit?.tokens?.light?.semantic) ? brandKit.tokens.light.semantic[semanticKey] : undefined;
  return colorToHex(fromRuntime ?? semantic);
}

const CHART_ROLES = {
  ink: ['foreground', 'foreground'],
  line: ['border', 'border'],
  muted: ['muted-foreground', 'mutedForeground'],
  surface: ['background', 'background'],
};

/**
 * One chart colour set for a page to print and the chart dialog to preview (`@uhuu/dialog-contracts`
 * `ChartDialogBrand`), all `#rrggbb`:
 *
 * - `palette`: the brand's chart colours when it set them (a brand opts into these), as many as
 *   `defaults.palette` has; else `defaults.palette`.
 * - `ink`, `line`, `muted`, `surface`: the template's value when `defaults` has one; else the kit's
 *   foreground, border, muted-foreground and background. Every kit carries those roles, so a template
 *   that passes them keeps its own chart design; one that leaves a role out follows the brand.
 *
 * A role neither side has is left out; the dialog fills it with its neutral default.
 *
 * @param {object|null|undefined} brandKit
 * @param {{ palette?: string[], ink?: string, line?: string, muted?: string, surface?: string }} [defaults]
 */
export function brandChartBrand(brandKit, defaults = {}) {
  const fallback = Array.isArray(defaults?.palette) ? defaults.palette : [];
  const { colors } = brandChartPalette(brandKit, { fallback, count: fallback.length || undefined });
  const brand = colors.length ? { palette: colors } : {};
  for (const [role, [runtimeName, semanticKey]] of Object.entries(CHART_ROLES)) {
    const value = colorToHex(defaults?.[role]) ?? roleColor(brandKit, runtimeName, semanticKey);
    if (value) brand[role] = value;
  }
  return brand;
}
