/**
 * Trying another published version of a template's brand before the template takes it: which
 * document a development page's `?brand=` names, or the `uhuu-components brand activate` argument,
 * and what differs between two brand documents. `BrandKitProvider` (the development preview) and
 * the `brand` command (src/cli/) share it; see docs/brand-kit-runtime.md, "Trying and activating a
 * brand version".
 *
 * A published version's document names itself, `generator.release = { teamId, kitId, version: 'vN',
 * url, appUrl }`, so `v9` is that `url` with `/versions/v9/`. Only immutable `…/versions/vN/` links
 * are accepted: a kit's root `brandkit.json` and `versions/latest/` follow every publish.
 *
 * Pure and DOM-free.
 */
import { isPlainObject, textOf } from '../utility/json.js';
import { brandKitLogo } from './brand-kit-assets.js';
import { brandKitRuntime } from './brand-kit-css-vars.js';
import { isPublicBrandKitJsonVersion, KIT_RUNTIME_VERSION } from '@uhuu/brandkit';

/** `?brand=` on a template's development page names the candidate. */
export const BRAND_PREVIEW_QUERY_PARAM = 'brand';

// A published version's name as Brand Kit writes it (`v0` is a kit with none yet).
const VERSION = /^v[1-9]\d*$/;
const VERSION_IN_PATH = /\/versions\/(v[1-9]\d*)\//;
const VERSION_DOCUMENT = /\/versions\/v[1-9]\d*\/brandkit\.json$/;
// Current Brand Kit documents: brandkit.json "1.x" carrying `runtime` version 1.
const LOCAL_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]']);

/**
 * Where Brand Kit publishes brands: `BRANDKIT_TRUSTED_ORIGINS` in `@uhuu/brandkit` (plan P3). This
 * package cannot import it, so it keeps a copy; test/brand-kit-conformance.test.mjs fails when the
 * copy differs from Brand Kit's conformance suite. A version link from any other host is refused.
 */
export const BRANDKIT_TRUSTED_ORIGINS = Object.freeze([
  'https://uhuu-brandkit.s3.eu-west-1.amazonaws.com',
  'https://brandkit.uhuu.io',
  'https://uhuu-layout-kit.s3.eu-west-1.amazonaws.com',
]);

function isTrustedOrigin(url, extraOrigins = []) {
  if (LOCAL_HOSTS.has(url.hostname)) return true;
  return [...BRANDKIT_TRUSTED_ORIGINS, ...extraOrigins].some((origin) => parseUrl(origin)?.origin === url.origin);
}

function parseUrl(value, base) {
  try {
    return new URL(value, base);
  } catch {
    return null;
  }
}

/** https, or http on this machine, without credentials. */
function isFetchable(url) {
  return Boolean(url) && !url.username && !url.password &&
    (url.protocol === 'https:' || (url.protocol === 'http:' && LOCAL_HOSTS.has(url.hostname)));
}

/** True for an absolute `https://…/versions/vN/brandkit.json` (http only on localhost). */
export function isBrandKitVersionUrl(value) {
  const url = typeof value === 'string' ? parseUrl(value) : null;
  return isFetchable(url) && VERSION_DOCUMENT.test(url.pathname);
}

/** The `vN` a URL's path names (`…/versions/v9/…` → `v9`), if any. */
export function brandKitUrlVersion(value) {
  const url = typeof value === 'string' ? parseUrl(value, 'http://localhost/') : null;
  return url ? VERSION_IN_PATH.exec(url.pathname)?.[1] : undefined;
}

/**
 * `generator.release` of a published version's document when it can name other versions (a `vN`
 * version and a version link), else `undefined`: older documents have none.
 *
 * @returns {{ version: string, url: string, teamId?: string, kitId?: string, appUrl?: string } | undefined}
 */
export function brandKitRelease(brandKit) {
  const release = isPlainObject(brandKit) && isPlainObject(brandKit.generator) ? brandKit.generator.release : undefined;
  if (!isPlainObject(release)) return undefined;
  const version = textOf(release.version);
  const url = textOf(release.url);
  if (!version || !VERSION.test(version) || !isBrandKitVersionUrl(url)) return undefined;
  const teamId = typeof release.teamId === 'number' ? String(release.teamId) : textOf(release.teamId);
  const kitId = textOf(release.kitId);
  const appUrl = textOf(release.appUrl);
  return { version, url, ...(teamId ? { teamId } : {}), ...(kitId ? { kitId } : {}), ...(appUrl ? { appUrl } : {}) };
}

/** Another version's document: `release.url` with `/versions/vN/` set to `version`. */
export function brandKitVersionUrl(release, version) {
  const url = new URL(release.url);
  url.pathname = url.pathname.replace(VERSION_IN_PATH, `/versions/${version}/`);
  return url.toString();
}

/**
 * Where Brand Kit says which version is newest, without a session: it answers with a redirect
 * whose path names `versions/vN/`. Read the redirect, never render what it points at.
 */
export function brandKitLatestManifestUrl(release) {
  const app = release?.appUrl ? parseUrl(release.appUrl) : null;
  if (!isFetchable(app) || !release.teamId || !release.kitId) return undefined;
  const base = release.appUrl.replace(/\/+$/, '');
  return `${base}/api/brandkit/teams/${encodeURIComponent(release.teamId)}/kits/${encodeURIComponent(release.kitId)}` +
    '/versions/latest/export/manifest.json';
}

/** The `?brand=` value on a location search string, `null` when there is none. */
export function brandPreviewFromSearch(search) {
  if (typeof search !== 'string' || !search) return null;
  try {
    return new URLSearchParams(search).get(BRAND_PREVIEW_QUERY_PARAM);
  } catch {
    return null;
  }
}

/**
 * The document a `?brand=` value, or a `brand activate` argument, names:
 *
 * - `vN`: that version of the brand the template holds (its `generator.release`);
 * - a version link, `https://…/versions/vN/brandkit.json` on a Brand Kit origin
 *   (`BRANDKIT_TRUSTED_ORIGINS`, plus `extraOrigins`; http only on localhost);
 * - with `origin` (the page's URL), a path on that origin such as `/candidate.json`, a draft
 *   downloaded from Brand Kit into the template's `public/`.
 *
 * Anything else is refused with the reason: a kit's root `brandkit.json`, `versions/latest/`,
 * `latest`, plain http, a path on another origin.
 *
 * @param {unknown} value
 * @param {{ brandKit?: unknown, origin?: string, extraOrigins?: readonly string[] }} [options]
 * @returns {{ input: string, url: string, version?: string } | { input: string, error: string }}
 */
export function resolveBrandCandidate(value, options = {}) {
  const input = typeof value === 'string' ? value.trim() : '';
  const kinds = `a version (v9), a version link (…/versions/vN/brandkit.json)${options.origin ? ' or a path on this page\'s origin (/candidate.json)' : ''}`;
  if (!input) return { input, error: `it is empty: pass ${kinds}` };
  if (VERSION.test(input)) {
    const release = brandKitRelease(options.brandKit);
    if (!release) {
      return { input, error: `${input} needs the template's brandkit.json to name its published version (generator.release); pass the version link instead` };
    }
    return { input, url: brandKitVersionUrl(release, input), version: input };
  }
  if (options.origin && input.startsWith('/') && !input.startsWith('//')) {
    const page = parseUrl(options.origin);
    const url = page ? parseUrl(input, page) : null;
    // `/\host/…` is another host to a URL parser: compare origins, not the first character.
    if (!url || url.origin !== page.origin) return { input, error: `${input} is not a path on this page's origin` };
    const version = VERSION_IN_PATH.exec(url.pathname)?.[1];
    return { input, url: url.toString(), ...(version ? { version } : {}) };
  }
  const url = /^https?:\/\//i.test(input) ? parseUrl(input) : null;
  if (!url) return { input, error: `${input} is not ${kinds}` };
  if (!isFetchable(url)) return { input, error: `${input} is not an https link without credentials` };
  if (!isTrustedOrigin(url, options.extraOrigins)) {
    return { input, error: `${url.origin} is not a Brand Kit origin (${BRANDKIT_TRUSTED_ORIGINS.join(', ')})` };
  }
  if (!VERSION_DOCUMENT.test(url.pathname)) {
    return {
      input,
      error: `${input} is not a published version (…/versions/vN/brandkit.json): a kit's root brandkit.json and versions/latest change with every publish`,
    };
  }
  return { input, url: url.toString(), version: VERSION_IN_PATH.exec(url.pathname)[1] };
}

/**
 * Why a fetched document is not a current Brand Kit document (brandkit.json "1.x" with `runtime` version 1),
 * or `undefined` when it is one.
 */
export function brandKitDocumentProblem(document) {
  if (!isPlainObject(document)) return 'it is not a JSON object';
  if (!isPublicBrandKitJsonVersion(document.version)) {
    return `its version is ${JSON.stringify(document.version ?? null)}, not 1.x`;
  }
  if (!isPlainObject(document.runtime) || document.runtime.version !== KIT_RUNTIME_VERSION) return `it has no runtime version ${KIT_RUNTIME_VERSION}`;
  return undefined;
}

/** "Walde v8": the brand's name and its version (default: the one its document names). */
export function brandKitLabel(brandKit, version = brandKitRelease(brandKit)?.version) {
  const name = isPlainObject(brandKit) ? textOf(brandKit.name) : undefined;
  return [name, version].filter(Boolean).join(' ') || undefined;
}

// --- What changed -------------------------------------------------------------------------------

/** `runtime.light`, the variables the provider applies, as strings. */
function runtimeVariables(brandKit) {
  const light = brandKitRuntime(brandKit)?.light ?? {};
  return Object.fromEntries(Object.entries(light)
    .filter(([, value]) => typeof value === 'string' || typeof value === 'number')
    .map(([name, value]) => [name, String(value)]));
}

/** The family each font role uses (`assignments['font.sans']` → `sans`), then unassigned fonts by key. */
function fontFamilies(brandKit) {
  if (!isPlainObject(brandKit)) return {};
  const fonts = isPlainObject(brandKit.fonts) ? brandKit.fonts : {};
  const assignments = isPlainObject(brandKit.assignments) ? brandKit.assignments : {};
  const families = {};
  const assigned = new Set();
  for (const [slot, id] of Object.entries(assignments)) {
    if (!slot.startsWith('font.') || typeof id !== 'string') continue;
    assigned.add(id);
    const family = isPlainObject(fonts[id]) ? textOf(fonts[id].family) : undefined;
    if (family) families[slot.slice('font.'.length)] = family;
  }
  for (const [key, font] of Object.entries(fonts)) {
    const family = isPlainObject(font) ? textOf(font.family) : undefined;
    if (family && !assigned.has(key) && !(key in families)) families[key] = family;
  }
  return families;
}

/** The logo file a template gets for each kind, and for a dark ground when it is another file. */
function logoFiles(brandKit) {
  const files = {};
  for (const kind of ['primary', 'mark']) {
    const light = brandKitLogo(brandKit, { kind, background: 'light' })?.src;
    const dark = brandKitLogo(brandKit, { kind, background: 'dark' })?.src;
    if (light) files[kind] = light;
    if (dark && dark !== light) files[`${kind} on dark`] = dark;
  }
  return files;
}

function compare(kind, before, after, changes) {
  for (const name of new Set([...Object.keys(before), ...Object.keys(after)])) {
    if (before[name] === after[name]) continue;
    changes.push({ kind, name, ...(name in before ? { before: before[name] } : {}), ...(name in after ? { after: after[name] } : {}) });
  }
}

/**
 * What differs between two brand documents as a template sees them: the runtime variables
 * (`runtime.light`) added, changed or removed, the family of each font role, and the logo files.
 * A change has `before` and `after`; an added one only `after`, a removed one only `before`.
 *
 * @returns {Array<{ kind: 'variable'|'font'|'logo', name: string, before?: string, after?: string }>}
 */
export function brandKitChanges(before, after) {
  const changes = [];
  compare('variable', runtimeVariables(before), runtimeVariables(after), changes);
  compare('font', fontFamilies(before), fontFamilies(after), changes);
  compare('logo', logoFiles(before), logoFiles(after), changes);
  return changes;
}

/** One change as a line: `--primary: oklch(…) → oklch(…)`, `Font sans: added, Inter`. */
export function describeBrandKitChange(change) {
  const label = change.kind === 'font' ? `Font ${change.name}` : change.kind === 'logo' ? `Logo ${change.name}` : change.name;
  if (change.before === undefined) return `${label}: added, ${change.after}`;
  if (change.after === undefined) return `${label}: removed (was ${change.before})`;
  return `${label}: ${change.before} → ${change.after}`;
}
