/**
 * What a brand kit declares for loading its fonts: stylesheet links (Google Fonts or a CSS
 * provider) and `@font-face` rules for self-hosted files. `BrandKitProvider` renders both.
 *
 * Only what the kit's `runtime` declares is loaded: `fontStylesheets` and `fontFaces`. A family with none is assumed to be
 * loaded by the template (an `@import` in its CSS) and is not guessed at. Relative URLs resolve
 * against the kit's `baseUrl`, else the directory of `sourceUrl` (where the kit was fetched from).
 *
 * Pure and DOM-free.
 */
import { createRuntimeFontCss } from '@uhuu/brandkit';
import { isPlainObject } from '../utility/json.js';
import { brandKitRuntime } from './brand-kit-css-vars.js';
import { brandKitBaseUrl as baseUrlOf } from './brand-kit-assets.js';

/**
 * @param {object|null|undefined} brandKit
 * @param {{ sourceUrl?: string }} [options]
 * @returns {{ fontFaceCss: string, stylesheetUrls: string[] }}
 */
export function brandKitFontAssets(brandKit, options = {}) {
  if (!isPlainObject(brandKit)) return { fontFaceCss: '', stylesheetUrls: [] };
  // A current kit's runtime lists exactly what its four font roles need; the package turns it into
  // links and sanitised `@font-face` rules, the same text every host writes.
  const runtime = brandKitRuntime(brandKit);
  if (!runtime) return { fontFaceCss: '', stylesheetUrls: [] };
  return createRuntimeFontCss(runtime, { baseUrl: baseUrlOf(brandKit, options?.sourceUrl) });
}
