import { instantiateGroup, instantiatePage, isPageGroup, type PageItem } from './page-group-utils';
import { getPagePayload } from './template-data-provider';

/** New instance identities, with the same component references and page metadata. */
export function duplicatePageItem(source: PageItem): PageItem {
  const templateId = source.templateId ?? source.id;
  if (!isPageGroup(source)) {
    const fresh = instantiatePage(templateId, source.componentKey ?? templateId, { repeatable: true });
    return { ...source, id: fresh.id, templateId, componentKey: fresh.componentKey };
  }

  const fresh = instantiateGroup(templateId, source.pages.map((page) => ({
    key: page.componentKey ?? page.templateId ?? page.id,
    dataKey: page.dataKey,
    hasFlow: page.hasFlow,
  })), { repeatable: true });
  return {
    ...source,
    id: fresh.id,
    templateId,
    pages: source.pages.map((page, index) => ({ ...page, id: fresh.pages[index].id })),
  };
}

// Template payloads are JSON values; copy nested objects and arrays as well as the slot itself.
function copyValue(value: any): any {
  if (Array.isArray(value)) return value.map(copyValue);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, copyValue(child)]));
  }
  return value;
}

/** Snapshot all instance data through TemplateDataProvider before the new order is persisted. */
export function copyDuplicatedItemPayload(payload: any, source: PageItem, clone: PageItem, items: PageItem[] = []): any {
  const pairs = [[source, clone]];
  if (isPageGroup(source) && isPageGroup(clone)) {
    source.pages.forEach((page, index) => pairs.push([page as PageItem, clone.pages[index] as PageItem]));
  }

  const next = { ...(payload ?? {}) };
  const otherGroupPrefixes = items.filter((item) => isPageGroup(item) && item.id !== source.id)
    .map((item) => `${item.id}__`);
  for (const section of ['pages', 'groups', 'integrations']) {
    const slots = { ...(payload?.[section] ?? {}) };
    let changed = false;
    for (const [from, to] of pairs) {
      if (slots[from.id] !== undefined) {
        slots[to.id] = copyValue(slots[from.id]);
        changed = true;
      }
    }
    // A dynamic group's inactive layouts also own page slots. Preserve them on duplication,
    // so switching layout after a save/restore keeps the copied edits under the new group id.
    if (isPageGroup(source)) {
      const prefix = `${source.id}__`;
      for (const [key, value] of Object.entries(payload?.[section] ?? {})) {
        if (key.startsWith(prefix) && !otherGroupPrefixes.some((other) => key.startsWith(other))) {
          slots[`${clone.id}__${key.slice(prefix.length)}`] = copyValue(value);
          changed = true;
        }
      }
    }
    if (changed) next[section] = slots;
  }

  // Materialize template/group/legacy defaults into independent instance slots too. Subsequent
  // edits use pages.<instanceId>, exactly as page dialogs and payload-backed options do.
  for (const [from, to] of pairs) {
    const value = getPagePayload(payload, from);
    if (value !== undefined && next.pages?.[to.id] === undefined) {
      next.pages = { ...(next.pages ?? {}), [to.id]: copyValue(value) };
    }
  }
  return next;
}
