// The empty state of a text binding, shared by the components that render one (Editable,
// Flow.Document). Internal: templates address the class, not this module.
import type { ReactNode } from 'react';

/**
 * Put on a bound text element that has nothing to show, so it stays addressable when it is
 * not literally `:empty` (a whitespace text node, an empty Flow inside it). The counterpart of
 * ImageBlock's `uhuu-image-empty`. `uhuu-indicators.css` gives it a one-line box in the editor
 * and applies no print layout rules.
 */
export const EMPTY_TEXT_CLASS = 'uhuu-text-empty';

const TEXT_DIALOG_TYPES = new Set(['text', 'textarea', 'markdown']);

export const isTextDialog = (dialog: unknown): boolean =>
  dialog !== null && typeof dialog === 'object' && 'type' in dialog &&
  typeof dialog.type === 'string' && TEXT_DIALOG_TYPES.has(dialog.type);

/**
 * True when `node` renders nothing a reader would see: null/undefined, a boolean, a
 * whitespace-only string, or a list of those. Numbers and elements count as content —
 * an element may well render nothing, but only its caller can know that, so a wrapper
 * passes `null` rather than an element around an empty string.
 */
export const isEmptyContent = (node: ReactNode): boolean => {
  if (node === null || node === undefined || typeof node === 'boolean') return true;
  if (typeof node === 'string') return node.trim() === '';
  if (Array.isArray(node)) return node.every(isEmptyContent);
  return false;
};
