import { useId, type ReactNode } from 'react';
import { Check, Minus, Plus } from 'lucide-react';
import { Button } from '../../ui/button';
import { Label } from '../../ui/label';
import { Select } from '../../ui/select';
import { Slider } from '../../ui/slider';
import { Switch } from '../../ui/switch';
import { cn } from '../../ui/cn';
import { useShellTranslation } from '../../i18n/locale-context';
import { findOptionChoice, isOptionOn, optionField, optionType, type OptionDefinition } from './option-core.js';

// The controls of an editor option, drawn the same for page options (a page's options menu) and
// document options (the toolbar's document options panel). The value comes in already read
// (option-core's readOptionValue); a choice goes out as the choice's own value, true / false for
// a toggle, or a number for a slider or counter.

export type OptionChoiceValue = string | number | boolean;

export interface OptionControlProps {
  definition: OptionDefinition;
  value: unknown;
  onChange: (value: OptionChoiceValue) => void;
}

// The select's value while the option holds a value among none of its choices.
const UNSET = '__uhuu_option_unset__';

const LABEL = 'uhuu:text-xs uhuu:font-medium uhuu:text-gray-500';

function asNumber(value: unknown): number | undefined {
  if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
  if (typeof value !== 'string' || value.trim() === '') return undefined;
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

function range(definition: OptionDefinition) {
  const min = typeof definition.min === 'number' ? definition.min : 0;
  const max = typeof definition.max === 'number' ? Math.max(definition.max, min) : Math.max(100, min);
  const step = typeof definition.step === 'number' && definition.step > 0 ? definition.step : 1;
  return { min, max, step };
}

function clamp(value: unknown, { min, max }: { min: number; max: number }) {
  const number = asNumber(value) ?? min;
  return Math.min(max, Math.max(min, number));
}

/** One option: its label, its control and its description. */
export function OptionControl({ definition, value, onChange }: OptionControlProps) {
  const { t, localize } = useShellTranslation();
  const id = useId();
  const controlId = `${id}control`;
  const labelId = `${id}label`;
  const descriptionId = `${id}description`;
  const label = localize(definition.label) ?? optionField(definition) ?? '';
  const descriptionText = localize(definition.description);
  const describedBy = descriptionText ? descriptionId : undefined;
  const description: ReactNode = descriptionText
    ? <p id={descriptionId} className="uhuu:text-xs uhuu:leading-snug uhuu:text-gray-500">{descriptionText}</p>
    : null;
  const choices = Array.isArray(definition.options) ? definition.options : [];

  switch (optionType(definition)) {
    case 'toggle':
      return (
        <div className="uhuu:flex uhuu:flex-col uhuu:gap-1">
          <div className="uhuu:flex uhuu:min-h-8 uhuu:items-center uhuu:justify-between uhuu:gap-3">
            <Label htmlFor={controlId} className={LABEL}>{label}</Label>
            <Switch
              id={controlId}
              aria-describedby={describedBy}
              checked={isOptionOn(value)}
              onCheckedChange={(checked) => onChange(checked)}
            />
          </div>
          {description}
        </div>
      );

    case 'slider': {
      const bounds = range(definition);
      const number = clamp(value, bounds);
      return (
        <div className="uhuu:flex uhuu:flex-col uhuu:gap-2">
          <div className="uhuu:flex uhuu:items-center uhuu:justify-between uhuu:gap-3">
            <span id={labelId} className={LABEL}>{label}</span>
            <span className="uhuu:font-mono uhuu:text-xs uhuu:tabular-nums uhuu:text-gray-700">{number}</span>
          </div>
          <Slider
            aria-labelledby={labelId}
            thumbLabel={label}
            thumbDescribedBy={describedBy}
            min={bounds.min}
            max={bounds.max}
            step={bounds.step}
            value={[number]}
            onValueChange={(values) => onChange(values[0])}
          />
          {description}
        </div>
      );
    }

    case 'counter': {
      const bounds = range(definition);
      const number = clamp(value, bounds);
      const step = (direction: 1 | -1) => onChange(clamp(number + direction * bounds.step, bounds));
      return (
        <div className="uhuu:flex uhuu:flex-col uhuu:gap-1.5">
          <span id={labelId} className={cn(LABEL, 'uhuu:block')}>{label}</span>
          <div role="group" aria-labelledby={labelId} aria-describedby={describedBy} className="uhuu:flex uhuu:items-center uhuu:gap-1.5">
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="uhuu:h-8 uhuu:w-8 uhuu:shrink-0 uhuu:p-0"
              aria-label={t('options.decrease', { name: label })}
              disabled={number <= bounds.min}
              onClick={() => step(-1)}
            >
              <Minus aria-hidden="true" className="uhuu:h-3.5 uhuu:w-3.5" />
            </Button>
            <output
              aria-live="polite"
              className="uhuu:flex uhuu:h-8 uhuu:flex-1 uhuu:items-center uhuu:justify-center uhuu:rounded-md uhuu:border uhuu:border-gray-200 uhuu:bg-gray-50 uhuu:font-mono uhuu:text-sm uhuu:font-medium uhuu:tabular-nums uhuu:text-gray-900"
            >
              {number}
            </output>
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="uhuu:h-8 uhuu:w-8 uhuu:shrink-0 uhuu:p-0"
              aria-label={t('options.increase', { name: label })}
              disabled={number >= bounds.max}
              onClick={() => step(1)}
            >
              <Plus aria-hidden="true" className="uhuu:h-3.5 uhuu:w-3.5" />
            </Button>
          </div>
          {description}
        </div>
      );
    }

    case 'color-series': {
      const selected = findOptionChoice(definition, value);
      return (
        <div className="uhuu:flex uhuu:flex-col uhuu:gap-1.5">
          <span id={labelId} className={cn(LABEL, 'uhuu:block')}>{label}</span>
          <div role="group" aria-labelledby={labelId} aria-describedby={describedBy} className="uhuu:flex uhuu:flex-wrap uhuu:gap-1.5">
            {choices.map((choice, index) => {
              const isSelected = choice === selected;
              const choiceLabel = localize(choice.label) ?? String(choice.value);
              return (
                <button
                  key={`${index}:${String(choice.value)}`}
                  type="button"
                  aria-label={choiceLabel}
                  aria-pressed={isSelected}
                  title={`${choiceLabel}${choice.hex ? ` (${choice.hex})` : ''}`}
                  onClick={() => onChange(choice.value)}
                  className={cn(
                    'uhuu:flex uhuu:h-7 uhuu:w-7 uhuu:items-center uhuu:justify-center uhuu:rounded-md uhuu:border-2 uhuu:transition-all uhuu:focus-visible:outline-none uhuu:focus-visible:ring-2 uhuu:focus-visible:ring-gray-400 uhuu:focus-visible:ring-offset-1',
                    isSelected
                      ? 'uhuu:scale-110 uhuu:border-gray-900'
                      : 'uhuu:border-gray-200 uhuu:hover:scale-105 uhuu:hover:border-gray-400',
                  )}
                  style={{ backgroundColor: choice.hex || String(choice.value) }}
                >
                  {isSelected && (
                    <Check aria-hidden="true" className="uhuu:h-4 uhuu:w-4 uhuu:text-white uhuu:drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]" strokeWidth={3} />
                  )}
                </button>
              );
            })}
          </div>
          {description}
        </div>
      );
    }

    default: {
      const choice = findOptionChoice(definition, value);
      const empty = value === undefined || value === null || value === '';
      return (
        <div className="uhuu:flex uhuu:flex-col uhuu:gap-1.5">
          <Label htmlFor={controlId} className={cn(LABEL, 'uhuu:block')}>{label}</Label>
          <Select
            id={controlId}
            aria-describedby={describedBy}
            value={choice ? String(choice.value) : UNSET}
            onChange={(event) => {
              const picked = choices.find((option) => String(option.value) === event.target.value);
              if (picked) onChange(picked.value);
            }}
          >
            {/* A value among none of the choices shows as it is, and cannot be picked again. */}
            {!choice && <option value={UNSET} disabled>{empty ? t('options.notSet') : String(value)}</option>}
            {choices.map((option, index) => (
              <option key={`${index}:${String(option.value)}`} value={String(option.value)}>
                {localize(option.label) ?? String(option.value)}
              </option>
            ))}
          </Select>
          {description}
        </div>
      );
    }
  }
}

/** Options stacked as page options and document options both list them. */
export function OptionControlList({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('uhuu:flex uhuu:flex-col uhuu:gap-3', className)}>{children}</div>;
}
