const METRIC_PROPERTIES = [
    ["ascentOverride", "ascent-override"],
    ["descentOverride", "descent-override"],
    ["lineGapOverride", "line-gap-override"],
];
/** Keeps the overrides that are finite percentages between 0 and 200; drops the rest. */
export function normalizeFontFaceMetrics(value) {
    const metrics = {};
    if (!value || typeof value !== "object")
        return metrics;
    for (const [key] of METRIC_PROPERTIES) {
        const raw = value[key];
        const number = typeof raw === "string" ? Number(raw.replace(/%$/, "")) : raw;
        if (typeof number === "number" && Number.isFinite(number) && number >= 0 && number <= 200)
            metrics[key] = Math.round(number * 100) / 100;
    }
    return metrics;
}
/** `["ascent-override", "92%"]` pairs for a face's overrides, in a fixed order. Every `@font-face` writer uses this. */
export function fontFaceMetricDeclarations(value) {
    const metrics = normalizeFontFaceMetrics(value);
    return METRIC_PROPERTIES.flatMap(([key, property]) => (metrics[key] === undefined ? [] : [[property, `${metrics[key]}%`]]));
}
