// src/index.js
// The shell's copy of the reset, for its chrome only (the pages keep a template's own base
// styles), and its `uhuu:` utilities, under [data-uhuu-interactive]. Both are unlayered, so the
// reset comes first, as preflight's `base` comes before `utilities`: at equal weight
// (`uhuu:space-y-3`, `:where()`-wrapped by Tailwind) the utility wins.
import './uhuu/styles/uhuu-editor-reset.css';
import './uhuu/styles/uhuu-editor-theme.css';
// Global preflight reset templates lay out against; utilities stay scoped to the shell.
import './uhuu/styles/uhuu-document-base.css';
// Light/dark shell chrome, keyed on <html data-uhuu-appearance> (docs/editor-shell-appearance.md).
import './uhuu/styles/uhuu-appearance.css';

import PaginationStatic from './uhuu/pagination-static/pagination-static';
import SheetStatic from './uhuu/pagination-static/sheet-static';
import { usePaginationHold } from './uhuu/pagination-static/pagination-hold';
import { useView } from './uhuu/pagination-static/view';
import { FlowArea, FlowPage, Flow as FlowItems, FlowColumns } from './uhuu/pagination-static/flow-static';
import { FlowText } from './uhuu/pagination-static/flow-text';
import * as flowMeasure from './uhuu/pagination-static/flow-measure';
import { distributeFlowColumns, distributeFlowItems } from './uhuu/pagination-static/flow-core';
import { FlowDocument } from './uhuu/pagination-static/flow-document';
import { markdownToFlowItems } from './uhuu/pagination-static/markdown-flow';
import { htmlToFlowItems } from './uhuu/pagination-static/html-flow';
import FrameBlock from './uhuu/frame/frame-block';
import { openFrame, frameEditDialog } from './uhuu/frame/frame-dialog.js';
import Editable from './uhuu/editable/editable';
import { getDialogProps } from './uhuu/editable/dialog-props';
import { BrandKitProvider, useBrandKit } from './uhuu/brand-kit/brand-kit-provider';
import { BRAND_KIT_PUBLIC_BASE_URL, brandKitSelection, loadBrandKit } from './uhuu/brand-kit/brand-kit-assets';
import { TemplateDataProvider } from './uhuu/editor-shell/document/template-data-provider';
import { PageEditor } from './uhuu/editor-shell/document/page-editor';
import { InteractiveModeProvider, useInteractive } from './uhuu/editor-shell/interactive-mode-context';
import { useIntegrationAdapter } from './uhuu/editor-shell/document/integration-adapter';
import { DocumentOptions } from './uhuu/editor-shell/document/document-options';

// The package root exports feature namespaces, plus ImageBlock and imageUrl (the one exception,
// docs/future-proofing-uhuu-components.md). A member exists because a named template, host or
// documented contract uses it; test/package-root-exports.test.mjs pins every list below.

// Fixed printed pages and the pagination contract: the sheets PageEditor renders, used directly
// by templates without PageEditor.
export const Static = {
  Pagination: PaginationStatic,
  Sheet: SheetStatic,
  // Holds `data-uhuu-pagination` at `measuring` for template work the package cannot see.
  usePaginationHold,
  // The view the pages are drawn for (PageEditor `view`): `print` or `screen`.
  useView,
};

// Content whose length is not known up front, continuing onto generated pages
// (docs/static-flow-pagination.md).
export const Flow = {
  // An authored page with one variable-height region, or the region alone.
  Page: FlowPage,
  Area: FlowArea,
  // The items that flow across pages; Columns lays them out in columns.
  Items: FlowItems,
  Columns: FlowColumns,
  // Text an item may split between lines (one per item).
  Text: FlowText,
  // A whole HTML body as a flow.
  Document: FlowDocument,
  // Markdown or HTML source as flow items.
  fromMarkdown: markdownToFlowItems,
  fromHtml: htmlToFlowItems,
  // For a host that measures its own canvas (Template Studio): the same deterministic planners
  // FlowArea uses, and the DOM readers it measures with, so page boundaries never drift by a
  // rounding step.
  planChunks: distributeFlowItems,
  planColumnChunks: distributeFlowColumns,
  measure: flowMeasure,
};

// Bleed, spread and plain images, and print-aware image URLs.
export { default as ImageBlock } from './uhuu/image/image-block';
export { imageUrl } from './uhuu/image/image-url';

// An image slot that several dialogs write (map, satellite, cadastral, pick, crop, annotation),
// saved as one `uhuu.frame.v1` value. Only the editor writes frames.
export const Frame = {
  Block: FrameBlock,
  // Opening a frame from a template's own element, or as an ImageBlock `dialog`.
  open: openFrame,
  editDialog: frameEditDialog,
};

// Dialog-backed editing of template content: a region that opens its dialog, and the props a
// template's own element binds (renderer guard and `data-uhuu-type` included).
export const Editing = {
  Editable,
  getDialogProps,
};

// Brand kits: one applied around the pages (print-safe colours, the kit's fonts), the kit's
// helpers inside it, and reading which kit a document selects outside it.
export const BrandKit = {
  Provider: BrandKitProvider,
  useBrandKit,
  publicBaseUrl: BRAND_KIT_PUBLIC_BASE_URL,
  selection: brandKitSelection,
  load: loadBrandKit,
};

// The editor around the document.
export const EditorShell = {
  TemplateDataProvider,
  PageEditor,
  InteractiveModeProvider,
  useInteractive,
  useIntegrationAdapter,
  // Document-level switches for top-level payload keys, written as user edits
  // (docs/document-options.md). Replaces the platform's template theme options.
  DocumentOptions,
};
